attribute.read.cpp:
// THE ROW SET IS NOT FIXED. IComponent carries seven attributes; a cast to
// ISignal adds five more and a cast to IInputPort adds three, so which rows
// exist is decided by which interfaces this component actually has. A cast
// that does not succeed yields FEWER rows; it never yields a row whose
// value is null, which would claim the attribute exists and has no value.
//
// getLockedAttributes() is openDAQ's own statement that a named attribute
// may not be written on THIS component, and it is one of the two sources of
// read_only. The other is the id having no setter at all. Neither is ever
// "this host has no writer": that would be a capability gap, and reporting
// it here would blame openDAQ for an absence in the host.
for (const auto& locked : component.getLockedAttributes())
    lockedByOpenDaq.insert(lowercased(toStd(locked)));

// The seven every component has. openDAQ's own lockable names for four of
// them are exactly "Name", "Description", "Active" and "Visible" --
// component_impl.h spells that set as COMPONENT_AVAILABLE_ATTRIBUTES.
addRow("name", "Name", toStd(component.getName()), "string", true, "Name");
addRow("description", "Description", toStd(component.getDescription()), "string", true, "Description");
addRow("active", "Active", static_cast<bool>(component.getActive()), "bool", true, "Active");
// The two ids openDAQ assigns and nothing can write.
addRow("global_id", "Global ID", toStd(component.getGlobalId()), "string", false, "");
addRow("local_id", "Local ID", toStd(component.getLocalId()), "string", false, "");

// Tags are a list of strings behind ITags, whose read side is getList().
service::Json tagList = service::Json::array();
if (const auto tags = component.getTags(); tags.assigned())
    for (const auto& tag : tags.getList())
        tagList.push_back(toStd(tag));
addRow("tags", "Tags", std::move(tagList), "string_list", true, "Tags");

addRow("visible", "Visible", static_cast<bool>(component.getVisible()), "bool", true, "Visible");

// Five more when this component is a signal.
if (const auto signal = component.asPtrOrNull<ISignal>(); signal.assigned())
{
    addRow("public", "Public", static_cast<bool>(signal.getPublic()), "bool", true, "Public");

    // What crosses the wire is the ID of the related signal and not the
    // signal object, which is why these two wire ids carry the _id/_ids
    // suffix that openDAQ's own member names do not.
    const auto domainSignal = signal.getDomainSignal();
    addRow("domain_signal_id",
           "Domain Signal ID",
           domainSignal.assigned() ? toStd(domainSignal.getGlobalId()) : std::string(),
           "string",
           false,
           "DomainSignal");

    service::Json relatedIds = service::Json::array();
    if (const auto related = signal.getRelatedSignals(); related.assigned())
        for (const auto& other : related)
            relatedIds.push_back(toStd(other.getGlobalId()));
    addRow("related_signal_ids",
           "Related Signals IDs",
           std::move(relatedIds),
           "string_list",
           false,
           "RelatedSignals");

    // getStreamed and getLastValue are the two reads a plain in-process
    // signal can refuse: streaming state belongs to a mirrored signal, and
    // a signal that has produced no packet has no last value. A refusal
    // drops the row rather than reporting a value openDAQ did not give.
    try
    {
        addRow("streamed", "Streamed", static_cast<bool>(signal.getStreamed()), "bool", false, "");
    }
    catch (const DaqException& e)
    {
        std::cerr << "[opendaq] signal \"" << toStd(signal.getGlobalId())
                  << "\" refused getStreamed(), so no streamed attribute row is reported for it: "
                  << e.getErrorMessage() << "\n";
    }

    try
    {
        const auto lastValue = signal.getLastValue();
        addRow("last_value",
               "Last Value",
               lastValue.assigned() ? toJson(lastValue) : service::Json(nullptr),
               attributeWireValueType(lastValue),
               false,
               "");
    }
    catch (const DaqException& e)
    {
        std::cerr << "[opendaq] signal \"" << toStd(signal.getGlobalId())
                  << "\" refused getLastValue(), so no last_value attribute row is reported for it: "
                  << e.getErrorMessage() << "\n";
    }
}

// Three more when it is an input port. A component is never both, so the
// second public row here cannot collide with the signal's.
if (const auto inputPort = component.asPtrOrNull<IInputPort>(); inputPort.assigned())
{
    addRow("public", "Public", static_cast<bool>(inputPort.getPublic()), "bool", true, "Public");

    const auto connected = inputPort.getSignal();
    addRow("signal_id",
           "Signal ID",
           connected.assigned() ? toStd(connected.getGlobalId()) : std::string(),
           "string",
           false,
           "");

    addRow("requires_signal",
           "Requires Signal",
           static_cast<bool>(inputPort.getRequiresSignal()),
           "bool",
           false,
           "");
}

// One panel, one call. The attributes view is a panel over ONE selected
// component, so every row it draws is read here in a single pass by the
// shared region component-attribute-rows.
rows = componentAttributeRows(component);

attribute.read.rust:
// ONE call decides read_only for every row below.
// IComponent::getLockedAttributes() answers the attribute names
// openDAQ has locked on THIS component -- the strings are openDAQ's
// own, from COMPONENT_AVAILABLE_ATTRIBUTES {"Name", "Description",
// "Visible", "Active"}, SIGNAL_AVAILABLE_ATTRIBUTES {"Public",
// "DomainSignal", "RelatedSignals"} and
// INPUT_PORT_AVAILABLE_ATTRIBUTES {"Public"}. It is read once here
// rather than per row, because the answer is per component.
let locked_attributes = component.locked_attributes();

// The seven every IComponent carries. Each is a getter on the
// interface itself, NOT an entry in the property bag: none of them
// is reachable through getPropertyValue, and the reference writes
// them with setattr rather than through the property API.
let name = component.name();
let description = component.description();
let active = component.active();
let global_id = component.global_id();
let local_id = component.local_id();
let visible = component.visible();
let tags = component.tags();

// ITags is READ-ONLY as an interface: it declares getList(),
// contains() and query() and nothing that changes the set.
// Adding, removing and replacing tags live on ITagsPrivate,
// a separate interface the tags object has to be queried
// for, so whether this component's tags can be written at
// all is established by that query rather than assumed.
let listed = tag_object.list();
let writable = tag_object.as_base_object().try_cast::<TagsPrivate>();

// Five more attributes exist only if the component carries ISignal,
// and three more only if it carries IInputPort. The two sets do not
// overlap except in `public`, which both declare. A cast that does
// not succeed yields FEWER ROWS -- never a row with a null value,
// which would claim the attribute exists and has none.
let signal_facet = component.as_base_object().try_cast::<Signal>();
let input_port_facet = component.as_base_object().try_cast::<InputPort>();

// The domain signal and the related signals are OBJECTS in
// openDAQ; what crosses this wire is their global ids, which is
// why the wire ids carry _id and _ids and the binding's own
// names (domain_signal, related_signals) do not.
let public = signal.public();
let streamed = signal.streamed();
let last_value = signal.last_value();
let domain_signal = signal.domain_signal();
let related_signals = signal.related_signals();

let public = input_port.public();
let requires_signal = input_port.requires_signal();
let connected_signal = input_port.signal();

// ONE PANEL, ONE CALL. The attributes view is a panel over one
// selected component, so every row it draws is read here in a single
// pass -- the shared region component-attribute-rows, which is also
// what set_component_attribute consults before it writes.
let rows = component_attribute_rows(&component, node_id);

attribute.read.csharp:
// The seven every IComponent carries. In the .NET binding each C++
// getter/setter pair has collapsed into a property, so there is no
// getName()/setName() to look for: it is Component.Name, and the four
// writable ones are the four that also declare a setter
// (set_Name, set_Description, set_Active, set_Visible).
Add("name", "Name", "string", WireStringOrEmpty(component.Name));
Add("description", "Description", "string", WireStringOrEmpty(component.Description));
Add("active", "Active", "bool", JsonValue.Create(component.Active));
Add("global_id", "Global ID", "string", WireStringOrEmpty(component.GlobalId));
Add("local_id", "Local ID", "string", WireStringOrEmpty(component.LocalId));

var tagList = new JsonArray();
var tags = component.Tags;
if (tags is not null)
    foreach (var tag in tags.List)
        tagList.Add(tag?.ToString() ?? "");
Add("tags", "Tags", "string_list", tagList);

Add("visible", "Visible", "bool", JsonValue.Create(component.Visible));

// The five an ISignal adds. domain_signal and related_signals hold
// OBJECTS in the binding; what crosses the wire is their global
// ids, which is why the wire ids carry _id and _ids and the
// reference's own Attribute keys ('.domain_signal',
// 'related_signals') do not.
var signal = component.Cast<Signal>();
Add("public", "Public", "bool", JsonValue.Create(signal.Public));

var domainSignal = signal.DomainSignal;
Add("domain_signal_id", "Domain Signal ID", "string",
    WireStringOrEmpty(domainSignal is null ? "" : domainSignal.GlobalId));

var relatedIds = new JsonArray();
var relatedSignals = signal.RelatedSignals;
if (relatedSignals is not null)
    foreach (var related in relatedSignals)
        relatedIds.Add(related?.GlobalId ?? "");
Add("related_signal_ids", "Related Signals IDs", "string_list", relatedIds);

Add("streamed", "Streamed", "bool", JsonValue.Create(signal.Streamed));

// ISignal.lastValue is an IBaseObject of whatever core type the
// signal's descriptor produced, and contract
// types.ComponentAttribute.value_type has no `any` member, so it
// crosses as the string the binding's ToString() gives -- which is
// the same thing the reference displays through
// utils.get_last_value_for_signal.
var lastValue = signal.LastValue;
Add("last_value", "Last Value", "string", WireStringOrEmpty(lastValue?.ToString()));

// The three an IInputPort adds. IInputPort.signal is a get-only
// property in this binding -- the writer is Connect(Signal), a
// different act with a different name -- so signal_id is read here
// and never written from this row.
var inputPort = component.Cast<InputPort>();
Add("public", "Public", "bool", JsonValue.Create(inputPort.Public));

var connectedSignal = inputPort.Signal;
Add("signal_id", "Signal ID", "string",
    WireStringOrEmpty(connectedSignal is null ? "" : connectedSignal.GlobalId));

Add("requires_signal", "Requires Signal", "bool", JsonValue.Create(inputPort.RequiresSignal));

foreach (var lockedAttribute in component.LockedAttributes)
    lockedByOpenDaq.Add(lockedAttribute?.ToString() ?? "");

var rootDevice = instance.RootDevice;
var rootId = rootDevice.GlobalId;

if (nodeId == rootId)
    return rootDevice;

if (nodeId.StartsWith(rootId + "/", StringComparison.Ordinal))
{
    var relative = nodeId.Substring(rootId.Length + 1);
    Component found = null;
    try
    {
        found = rootDevice.FindComponent(relative);
    }
    catch (OpenDaqException)
    {
        found = null;
    }
    if (found is not null)
        return found;
}

rows = ReadAttributeRowsOf(component, nodeId);  // shared region component-attribute-rows

