    lockedByOpenDaq.Add(lockedAttribute?.ToString() ?? "");

if (component.CanCastTo<Channel>())
    return "channel";
if (component.CanCastTo<Device>())
    return "device";
if (component.CanCastTo<FunctionBlock>())
    return "function_block";
if (component.CanCastTo<Signal>())
    return "signal";
