// The Instance is built with the module path from the manifest, so the
// device and function-block modules come from that directory and no
// other.
let builder = InstanceBuilder::new()
    .map_err(|e| format!("creating an openDAQ InstanceBuilder failed: {e}"))?;
builder
    .set_module_path(module_path)
    .map_err(|e| format!("setting the InstanceBuilder module path to {module_path} failed: {e}"))?;
builder
    .set_global_log_level(level)
    .map_err(|e| format!("setting the InstanceBuilder global log level to {level:?} failed: {e}"))?;
let instance = Instance::from_builder(&builder)
    .map_err(|e| format!("constructing the openDAQ Instance failed: {e}"))?;

// openDAQ has no "kind" attribute: a component's kind is whichever of the
// component interfaces it can be cast to, most-derived first, because a
// Channel is also a FunctionBlock and a Device is also a Folder. The
// opendaq crate does that probe once in BaseObject::component_kind(),
// which is Rust's spelling of the C++ host's chain of asPtrOrNull casts.
let kind = component.as_base_object().component_kind();
let wire_kind = match kind {
    Some(ComponentKind::Channel) => "channel",
    Some(ComponentKind::Device) => "device",
    Some(ComponentKind::FunctionBlock) => "function_block",
    Some(ComponentKind::Signal) => "signal",
    // A server is INVISIBLE to that probe. openDAQ's IServer derives from
    // IFolder, so component_kind() answers Folder for one, and the crate's
    // ComponentKind enum has no Server variant at all -- it is
    // (Channel, FunctionBlock, Device, Signal, InputPort, Folder, Component).
    // The only thing that tells a server row from a folder row is asking the
    // object for the IServer interface, which is what NodeKind's `server`
    // value and the row menu's discovery items both need.
    //
    // Input ports still fall through to "folder": the contract's NodeKind
    // has no input_port value, and this host does not invent one.
    _ => match component.as_base_object().try_cast::<Server>() {
        Some(_) => "server",
        None => "folder",
    },
};

// A property with selection values is a selection whatever its storage
// type says; otherwise the core type of the property decides.
if !property.selection_values()?.is_null() {
    return Ok(Some("selection"));
}
let wire_type = match property.value_type()? {
    CoreType::Bool => Some("bool"),
    CoreType::Int => Some("int"),
    CoreType::Float => Some("float"),
    CoreType::String => Some("string"),
    CoreType::Struct => Some("struct"),
    _ => None,
};

// Every component keeps a status container addressed by name. openDAQ's own
// two names are "ComponentStatus", whose EnumerationType is
// (Ok, Warning, Error), and "ConnectionStatus", whose EnumerationType is
// (Connected, Reconnecting, Unrecoverable, Removed); both are registered on
// the type manager in core/opendaq/modulemanager/src/context_impl.cpp. The
// value is an Enumeration, and its value() is the enumerator's own name.
// A container that keeps no status of that name answers
// OPENDAQ_ERR_NOTFOUND, which means "this component does not report it".
let found = container.status(status_name);
let enumerator_name = match found {
    Ok(Some(status)) => status.value().ok(),
    _ => None,
};

let message = container.status_message(status_name);

// openDAQ declares isLocked() on IDevice and nowhere else, so a component
// that is not a device has no lock state of its own and inherits the
// nearest ancestor device's -- which is exactly what the reference
// recomputes client side in gui_demo.py's _set_node_lock_status_recursive.
// Doing it here means one walk up the parent chain per row instead of a
// rule every client has to reimplement.
if let Some(device) = component.as_base_object().try_cast::<Device>() {
    return device.is_locked().ok();
}
let mut ancestor = component.parent().ok().flatten();
while let Some(current) = ancestor {
    if let Some(device) = current.as_base_object().try_cast::<Device>() {
        return device.is_locked().ok();
    }
    ancestor = current.parent().ok().flatten();
}

// openDAQ's OperationModeType, declared in
// core/opendaq/component/include/opendaq/component.h, is (Unknown, Idle,
// Operation, SafeOperation). The wire carries the same four, lowercased
// with an underscore join. The opendaq crate marks the enum
// #[non_exhaustive], so a variant a later SDK adds reaches the wildcard and
// is reported as "not a mode this contract carries" rather than being
// mislabelled as one of the four.
let wire_name = match mode {
    OperationModeType::Unknown => Some("unknown"),
    OperationModeType::Idle => Some("idle"),
    OperationModeType::Operation => Some("operation"),
    OperationModeType::SafeOperation => Some("safe_operation"),
    _ => None,
};

let mode = match wire_name {
    "unknown" => Some(OperationModeType::Unknown),
    "idle" => Some(OperationModeType::Idle),
    "operation" => Some(OperationModeType::Operation),
    "safe_operation" => Some(OperationModeType::SafeOperation),
    _ => None,
};

// IPropertyObject::getUpdating(Bool*) (property_object.h:361) answers "a
// beginUpdate has been called on this object and no endUpdate has closed
// it", and while that holds every setPropertyValue against the object is
// STAGED rather than applied. Almost every openDAQ component is an
// IPropertyObject, but not literally every one, so the facet is queried
// rather than assumed and a component without it reports null.
let updating = component
    .as_base_object()
    .try_cast::<PropertyObject>()
    .and_then(|object| object.updating().ok());

// A recorder is a function block that ALSO carries IRecorder, which is
// where getIsRecording(), startRecording() and stopRecording() live
// (recorder.h:62 and below). Nothing about a function block's type id or its
// place in the tree says whether it is one, so the question is an interface
// query -- the same one the reference asks with
// daq.IRecorder.can_cast_from(self.node) before it builds RecorderView
// (block_view.py:169-171).
let recorder = component.as_base_object().try_cast::<Recorder>();

// Identity, then the two structural facts openDAQ exposes: a component
// knows its parent, and a component that is a Folder knows its items.
// Properties come from the PropertyObject facet, which most but not all
// components have.
let id = component.global_id().map_err(|e| translate_general(&e))?;
let name = component.name().map_err(|e| translate_general(&e))?;
let kind = kind_of(component); // shared region component-kind

let parent_id = match component.parent().map_err(|e| translate_general(&e))? {
    Some(parent) => Some(parent.global_id().map_err(|e| translate_general(&e))?),
    None => None,
};

let mut child_ids = Vec::new();
if let Some(folder) = component.as_base_object().try_cast::<Folder>() {
    for child in folder.items().map_err(|e| translate_general(&e))? {
        child_ids.push(child.global_id().map_err(|e| translate_general(&e))?);
    }
}

let mut property_ids = Vec::new();
if let Some(object) = component.as_base_object().try_cast::<PropertyObject>() {
    for property in object.all_properties().map_err(|e| translate_general(&e))? {
        if is_representable(&property) {
            // shared region property-wire-value-type
            property_ids.push(property.name().map_err(|e| translate_general(&e))?);
        }
    }
}

// The six state facts. active and the status container are asked of
// every component; the connection status and the operation mode are
// asked only where the component carries the Device interface, which is
// what "device rows only" in contract types.Node means. The lock state
// is the shared region effective-device-lock-state, which walks to the
// nearest ancestor device when this component is not one.
let device_facet = component.as_base_object().try_cast::<Device>();
let active = component.active().ok();
let locked = effective_locked(component); // shared region effective-device-lock-state
let status_container = component.status_container().ok().flatten();
let component_status_enumerator = status_container
    .as_ref()
    .and_then(|container| status_enumerator_name(container, "ComponentStatus"));
let component_status_message = match (&status_container, &component_status_enumerator) {
    (Some(container), Some(_)) => status_message(container, "ComponentStatus"),
    _ => None,
};
let connection_status_enumerator = match (&device_facet, &status_container) {
    (Some(_), Some(container)) => status_enumerator_name(container, "ConnectionStatus"),
    _ => None,
};
let operation_mode = match &device_facet {
    Some(_) => component
        .operation_mode()
        .ok()
        .and_then(operation_mode_wire_name), // shared region operation-mode-names
    None => None,
};

// The two facts added with the batched-update and recorder rows, and
// both are here for the same reason the six above are: a per-row fact
// must not cost a per-row call. `updating` is asked of every component,
// because the reference reads it on every component too
// (_set_node_update_status_recursive walks the whole tree). `recording`
// is null unless the component carries IRecorder, and that null means
// BOTH "not a recorder" and "not reported" -- the client draws no
// Start/Stop control either way.
let updating = batched_update_is_open_on(component); // shared region property-object-update-state
let recording = recorder_facet_of(component) // shared region recorder-of-component
    .and_then(|recorder| recorder.is_recording().ok());

function_block.add.cpp:
// The Instance is built with the module path from the manifest, and the
// core-event handler must be attached to the Context's OnCoreEvent before
// anything is added, or the additions that follow are never announced.
impl_->instance = InstanceFromBuilder(
    InstanceBuilder().setModulePath(modulePath).setGlobalLogLevel(static_cast<LogLevel>(logLevel)));

impl_->instance.getContext().getOnCoreEvent() +=
    [impl](const ComponentPtr& sender, const CoreEventArgsPtr& args) { impl->onCoreEvent(sender, args); };

// openDAQ has no "kind" attribute: a component's kind is whichever of these
// interfaces it can be cast to, and the order matters because a Channel is
// also a FunctionBlock and a Device is also a Folder.
if (component.asPtrOrNull<IChannel>().assigned())
    return "channel";
if (component.asPtrOrNull<IDevice>().assigned())
    return "device";
if (component.asPtrOrNull<IFunctionBlock>().assigned())
    return "function_block";
if (component.asPtrOrNull<ISignal>().assigned())
    return "signal";
// A server is a signal container, so without this arm it would fall through
// to "folder" and add_server would answer with a Node it cannot describe.
// It is tested after the four above because none of them can also be an
// IServer, and before the fallback because every IServer would otherwise
// reach it.
if (component.asPtrOrNull<IServer>().assigned())
    return "server";
// Everything else -- folders and plain components such as Synchronization --
// is reported as a folder; the contract's kind set has no other container.
return "folder";

// A property with selection values is a selection whatever its storage type
// says; otherwise the core type of the property decides.
if (property.getSelectionValues().assigned())
{
    out = "selection";
    return true;
}
switch (property.getValueType())
{
    case ctBool:   out = "bool";   return true;
    case ctInt:    out = "int";    return true;
    case ctFloat:  out = "float";  return true;
    case ctString: out = "string"; return true;
    case ctStruct: out = "struct"; return true;
    default:       return false;
}

// Statuses live in a container keyed by name, and a component carries only
// the statuses whoever built it added: a plain folder has none at all, and
// "ConnectionStatus" exists only on a device that a streaming client module
// built. Reading the whole dictionary once asks openDAQ what is actually
// there instead of guessing a key and catching the miss. The values are
// Enumerations of openDAQ's ComponentStatusType (Ok, Warning, Error) and
// ConnectionStatusType (Connected, Reconnecting, Unrecoverable, Removed).
const auto container = component.getStatusContainer();
if (!container.assigned())
    return DictPtr<IString, IEnumeration>();
return container.getStatuses();

// openDAQ declares lock, unlock and the operation modes on IDevice, not
// on IComponent, so the component has to be taken through its IDevice
// facet before any of them can be called. A component that does not
// carry that facet is not a device -- and it EXISTS, so refusing with
// not_found would be a lie; the contract's word for it is unsupported.
const auto device = component.asPtrOrNull<IDevice>();

// The lock is a DEVICE fact: only IDevice carries isLocked(). openDAQ has
// no "effective locked" for a component below a device, so the nearest
// IDevice ancestor -- the component itself, when it is a device -- is
// walked to and asked, and that answer is what the wire carries. The walk
// is exactly what the reference does client-side, once per row, in
// _set_node_lock_status_recursive; doing it host-side does it once.
for (ComponentPtr walker = component; walker.assigned(); walker = walker.getParent())
    if (const auto owningDevice = walker.asPtrOrNull<IDevice>(); owningDevice.assigned())
        return static_cast<bool>(owningDevice.isLocked());
return std::nullopt;

// OperationModeType is declared in <opendaq/component.h>. Its four members
// are the contract's Node.operation_mode values, and the wire spells the
// compound one in snake_case.
{OperationModeType::Unknown, "unknown"},
{OperationModeType::Idle, "idle"},
{OperationModeType::Operation, "operation"},
{OperationModeType::SafeOperation, "safe_operation"},

// getUpdating() is declared on IPropertyObject, which every openDAQ
// component carries, and it is true between a beginUpdate and its
// endUpdate. While it is true, a setPropertyValue against this component is
// HELD and not applied -- so a client that writes without looking at this
// is writing into a batch that nobody may ever end.
const auto object = component.asPtrOrNull<IPropertyObject>();
if (!object.assigned())
    return std::nullopt;
return static_cast<bool>(object.getUpdating());

// openDAQ declares startRecording, stopRecording and getIsRecording on
// IRecorder, which a recorder function block carries IN ADDITION to
// IFunctionBlock. Whether a component is a recorder AT ALL is this cast and
// nothing else -- no kind, no type id and no property says so -- which is
// the same question the reference asks with
// daq.IRecorder.can_cast_from(node) before it builds its RecorderView.
return component.asPtrOrNull<IRecorder>();

// getActive() is the EFFECTIVE active flag: false either because this
// component was deactivated or because a parent was.
node.active = static_cast<bool>(component.getActive());

// shared region effective-device-lock-state
node.locked = effectiveDeviceLockState(component);

// shared region property-object-update-state
node.updating = propertyObjectUpdatingState(component);

// shared region recorder-of-component. null on every component that is not a
// recorder, which is what tells a client to draw no Start/Stop control at
// all rather than to draw a stopped one. A recorder that refuses to report
// its own state keeps recording null and costs the row nothing else, which
// is why this one read has a catch of its own.
if (const auto recorder = recorderOrNull(component); recorder.assigned())
{
    try
    {
        node.recording = static_cast<bool>(recorder.getIsRecording());
    }
    catch (const DaqException& e)
    {
        std::cerr << "[opendaq] component \"" << toStd(component.getGlobalId())
                  << "\" carries IRecorder but refused getIsRecording(), so Node.recording stays null: "
                  << e.getErrorMessage() << "\n";
    }
}

// shared region component-status-container
const auto statuses = componentStatuses(component);

if (statuses.assigned() && statuses.hasKey("ComponentStatus"))
{
    node.component_status = lowercased(toStd(statuses.get("ComponentStatus").getValue()));
    const auto message = component.getStatusContainer().getStatusMessage("ComponentStatus");
    if (message.assigned() && !toStd(message).empty())
        node.component_status_message = toStd(message);
}

// connection_status and operation_mode are device facts. On anything else
// they stay null, which is what the contract asks for.
const auto device = component.asPtrOrNull<IDevice>();
if (!device.assigned())
    return;

if (statuses.assigned() && statuses.hasKey("ConnectionStatus"))
    node.connection_status = lowercased(toStd(statuses.get("ConnectionStatus").getValue()));

// getOperationMode() is the CURRENT mode. The AVAILABLE list is a separate
// call, get_device_operation_modes, because only an opened menu needs it.
node.operation_mode = operationModeWireName(device.getOperationMode());

// Identity, then the two structural facts openDAQ exposes: a component
// knows its parent, and a component that is a Folder knows its items.
// Properties come from the IPropertyObject facet, which most but not
// all components have.
node.id = toStd(component.getGlobalId());
node.name = toStd(component.getName());
node.kind = kindOf(component);  // shared region component-kind

if (const auto parent = component.getParent(); parent.assigned())
    node.parent_id = toStd(parent.getGlobalId());

if (const auto folder = component.asPtrOrNull<IFolder>(); folder.assigned())
    for (const auto& child : folder.getItems())
        node.child_ids.push_back(toStd(child.getGlobalId()));

if (const auto object = component.asPtrOrNull<IPropertyObject>(); object.assigned())
    for (const auto& property : object.getAllProperties())
        if (isRepresentable(property))  // shared region property-wire-value-type
            node.property_ids.push_back(toStd(property.getName()));

// What the loaded modules can instantiate right now, as a dictionary
// keyed by the very type id that add_function_block takes. This is a
// question about the modules, not about any one component, so it is
// asked of the Instance.
types = impl_->instance.getAvailableFunctionBlockTypes();

// The wire carries the ids only. The FunctionBlockType object also
// knows a display name and a description, which the M1 contract's
// array-of-string return has no room for.
for (const auto& [typeId, type] : types)
    out.push_back(StringPtr(typeId).toStdString());

// openDAQ hangs function blocks off a device, so the parent has to carry
// IDevice. A signal or a plain folder cannot own one.
const DevicePtr parentDevice = parent.asPtrOrNull<IDevice>();

// The device instantiates the type and places the new block in its own
// "FB" folder. That insertion is what makes openDAQ raise its
// ComponentAdded core event, which this host turns into the contract's
// component_added -- the operation itself pushes no event of its own.
added = parentDevice.addFunctionBlock(typeId);

// A function block is removed through the device that owns it, and openDAQ
// parents it under that device's "FB" folder rather than under the device
// directly -- so the owner is the nearest IDevice ancestor, not the parent.
for (ComponentPtr walker = component.getParent(); walker.assigned(); walker = walker.getParent())
{
    const DevicePtr candidate = walker.asPtrOrNull<IDevice>();
    if (candidate.assigned())
    {
        owner = candidate;
        break;
    }
}

// The removal is what makes openDAQ raise its ComponentRemoved core
// event, which this host turns into the contract's component_removed.
owner.removeFunctionBlock(functionBlock);

module.load.csharp:
// The Instance is built with the module path the manifest named, which
// is the directory openDAQ's loadModules() sweeps: every module
// list_loaded_modules answers with comes from here, and every module
// load_module_from_host_path adds comes from somewhere this sweep did
// not reach.
instance = OpenDAQFactory.Instance(modulePath, "quackoscope-host-csharp");

// IDeviceType, IFunctionBlockType, IServerType and IStreamingType all
// derive from IComponentType, which is where id, name and description
// live. connectionStringPrefix is NOT on IComponentType: only IDeviceType
// and IStreamingType declare it, which is why the caller passes it in and
// why contract types.ComponentTypeInfo.connection_string_prefix is
// nullable.
described.Id = componentType.Id;
described.Name = componentType.Name;
var description = componentType.Description;

// A module may answer OPENDAQ_ERR_NOTIMPLEMENTED for a dictionary it
// does not offer -- the MockModule loaded from the manifest's
// module_path does exactly that for availableStreamingTypes -- so the
// four are read one at a time and a refusal costs only its own kind
// instead of the whole module. gui_demo.py guards the same four reads
// the same way, with _safe_get in _draw_module_type_columns.
