if (!component.CanCastTo<PropertyObject>())
    throw new WireError(WireErrorCode.NotFound, $"component \"{nodeId}\" carries no properties");
var propertyObject = component.Cast<PropertyObject>();

// IPropertyObject::beginUpdate, spelled BeginUpdate() in the .NET
// binding. It is RECURSIVE over child property objects
// (property_object.h:335), so one call on a device puts the whole
// subtree into batch mode -- for every session, not just this one.
// While it holds, SetPropertyValue records the value instead of
// applying it.
propertyObject.BeginUpdate();

// IPropertyObject::endUpdate, spelled EndUpdate(). It APPLIES
// everything set since the matching beginUpdate, and it raises when
// no beginUpdate is open. This host does not swallow that the way
// gui_demo.py:1374-1378 does with a bare `except RuntimeError:
// pass` -- silence there would tell a user their batch was applied.
propertyObject.EndUpdate();

property.batched_update.cpp:
// beginUpdate is RECURSIVE over the component's child property objects,
// so one call on a device puts that whole subtree into batch mode. It is
// a state of the COMPONENT and not of this socket: every session sees
// it, through Node.updating, and every session's set_property_value on
// that subtree is held until an endUpdate arrives.
object.beginUpdate();

// endUpdate applies everything set since beginUpdate, and RAISES when no
// beginUpdate is open. The reference swallows exactly that with a bare
// `except RuntimeError: pass`; this host does not, because silence here
// would tell a user their batch was applied when nothing was.
object.endUpdate();

property.batched_update.rust:
// IPropertyObject::beginUpdate() (property_object.h:330-349). While
// it is open, setPropertyValue STAGES the value instead of applying
// it: reads still answer the old value and no OnPropertyValueWrite
// or OnEndUpdate event fires. It is RECURSIVE over child property
// objects (property_object.h:335), so one call on a device puts a
// whole subtree into batch mode -- for every session at once, not
// just the one that called it.
//
// The crate also offers an RAII bracket, BatchedPropertyUpdate,
// which opens the batch on construction and commits it on drop.
// That shape cannot serve these two rows: the contract's begin and
// end are two separate requests on two separate frames, and a guard
// that commits when its scope ends would end the batch before the
// client's next frame arrived.
let result = object.begin_update();

// IPropertyObject::endUpdate() applies everything staged since the
// matching beginUpdate, all at once, and fires the OnEndUpdate event
// with the list of changed properties. It raises when no beginUpdate
// is open.
let result = object.end_update();

